// Owner: M1
// Shadow-DOM shell. This is the only file that calls mount() / unmount().
// M2–M5: do not edit this file. Send messages to background.js instead.
// Your obstacle root must set pointer-events: auto. The page stays clickable
// everywhere else. Obstacles mount only in the visible tab. The timer shows
// on every tab.

import { mount as mountAds, unmount as unmountAds } from "./ads.js";
import { mount as mountCaptcha, unmount as unmountCaptcha } from "./captcha.js";
import { mount as mountBrightness, unmount as unmountBrightness } from "./brightness.js";
import { mount as mountLoading, unmount as unmountLoading } from "./loading.js";
import { mount as mountChat, unmount as unmountChat } from "./chatbot.js";

const LIVE = ["ads", "captcha", "browsing"];

const GROUPS = {
  ads: [[mountAds, unmountAds]],
  captcha: [[mountCaptcha, unmountCaptcha]],
  browsing: [
    [mountAds, unmountAds],
    [mountBrightness, unmountBrightness],
    [mountLoading, unmountLoading],
    [mountChat, unmountChat]
  ]
};

if (!window.__pisonetShell) {
  window.__pisonetShell = true;
  boot();
}

function boot() {
  const host = document.createElement("div");
  host.style.position = "fixed";
  host.style.inset = "0";
  host.style.zIndex = "2147483647";
  host.style.pointerEvents = "none";
  document.documentElement.append(host);

  const shadow = host.attachShadow({ mode: "open" });
  const style = document.createElement("style");
  shadow.append(style);
  loadCss(style);

  // Google blocks innerHTML. Build the shell with createElement or the popup never mounts.
  const root = document.createElement("div");
  root.className = "shell-root";
  const frame = document.createElement("div");
  frame.className = "bamboo-frame";
  frame.hidden = true;
  ["top", "right", "bottom", "left"].forEach((side) => {
    const rail = document.createElement("div");
    rail.className = `bamboo-rail bamboo-${side}`;
    frame.append(rail);
  });
  const bar = document.createElement("div");
  bar.className = "hud-bar";
  bar.hidden = true;
  const time = document.createElement("button");
  time.className = "hud-time";
  time.type = "button";
  time.textContent = "00:00:00";
  time.setAttribute("aria-label", "Time left. Opens session tools.");
  bar.append(time);
  const toast = document.createElement("div");
  toast.className = "hud-toast";
  toast.hidden = true;
  const panel = document.createElement("div");
  panel.className = "god-panel";
  panel.hidden = true;
  const title = document.createElement("div");
  title.textContent = "session tools";
  panel.append(title);
  [
    ["skip", "Next phase"],
    ["addTime", "Add 30 seconds"],
    ["clearAds", "Clear ads"],
    ["passCaptcha", "Pass CAPTCHA"]
  ].forEach(([action, label]) => {
    const button = document.createElement("button");
    button.type = "button";
    button.dataset.god = action;
    button.textContent = label;
    panel.append(button);
  });
  const brightLabel = document.createElement("label");
  brightLabel.append(document.createTextNode("Brightness "));
  const bright = document.createElement("input");
  bright.type = "number";
  bright.min = "1";
  bright.max = "100";
  bright.value = "1";
  bright.setAttribute("data-bright", "");
  brightLabel.append(bright);
  const reset = document.createElement("button");
  reset.type = "button";
  reset.dataset.god = "reset";
  reset.textContent = "Reset demo";
  panel.append(brightLabel, reset);
  const stage = document.createElement("div");
  stage.className = "shell-stage";
  // Stage first, frame and timer after, so the bamboo stays above ads and obstacles.
  root.append(stage, frame, bar, toast, panel);
  shadow.append(root);

  let active = [];
  let signature = "";
  let toastTimer = 0;

  time.addEventListener("click", () => {
    panel.hidden = !panel.hidden;
    bright.value = String(bright.value || 1);
  });

  panel.addEventListener("click", (event) => {
    const action = event.target?.dataset?.god;
    if (!action) return;
    const message = { type: "god", action };
    if (action === "setBrightness") return;
    chrome.runtime.sendMessage(message);
  });

  bright.addEventListener("change", () => {
    chrome.runtime.sendMessage({
      type: "god",
      action: "setBrightness",
      value: bright.value
    });
  });

  chrome.storage.onChanged.addListener((changes, area) => {
    if (area === "local" && changes.state?.newValue) render(changes.state.newValue);
  });
  chrome.runtime.sendMessage({ type: "getState" }, (result) => render(result?.state));

  setInterval(() => {
    chrome.runtime.sendMessage({ type: "tickCheck" });
    chrome.runtime.sendMessage({ type: "getState" }, (result) => {
      if (result?.state) paintTime(result.state);
    });
  }, 1000);

  document.addEventListener("visibilitychange", () => {
    chrome.runtime.sendMessage({ type: "getState" }, (result) => render(result?.state));
  });
  window.addEventListener("pageshow", () => {
    chrome.runtime.sendMessage({ type: "getState" }, (result) => render(result?.state));
  });

  function render(state) {
    if (!state) return;
    const live = LIVE.includes(state.phase) && state.endsAt;
    bar.hidden = !live;
    frame.hidden = !live;
    if (!live) panel.hidden = true;
    paintTime(state);
    bright.value = String(state.brightness || 1);

    const group = GROUPS[state.phase] || [];
    const nextSignature = `${state.phase}:${state.clearToken}`;
    if (nextSignature === signature) return;
    signature = nextSignature;
    active.forEach((unmount) => unmount());
    active = [];
    group.forEach(([mount, unmount]) => {
      try {
        mount(stage, state);
        active.push(unmount);
      } catch (err) {
        showToast("Overlay module failed.");
        console.error(err);
      }
    });
  }

  function paintTime(state) {
    if (!state.endsAt) {
      time.textContent = "00:00:00";
      return;
    }
    const left = Math.max(0, state.endsAt - Date.now());
    const total = Math.ceil(left / 1000);
    const hours = String(Math.floor(total / 3600)).padStart(2, "0");
    const minutes = String(Math.floor((total % 3600) / 60)).padStart(2, "0");
    const seconds = String(total % 60).padStart(2, "0");
    time.textContent = `${hours}:${minutes}:${seconds}`;
  }

  function showToast(text) {
    toast.hidden = false;
    toast.textContent = text;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => {
      toast.hidden = true;
    }, 2200);
  }
}

async function loadCss(style) {
  const files = ["overlay/overlay.css", "overlay/ads.css", "overlay/popups.css"];
  const parts = await Promise.all(files.map(async (file) => {
    const response = await fetch(chrome.runtime.getURL(file));
    return response.text();
  }));
  style.textContent = parts.join("\n");
}
